def main(argv: Optional[List[str]] = None) -> int:
    parser = argparse.ArgumentParser(description="RAG system with metadata filtering and ranking")
    parser.add_argument("--query", help="user query")
    parser.add_argument("--k", type=int, default=5, help="number of results (default 5)")
    parser.add_argument("--ranker", choices=["cosine", "mmr"], default="cosine")
    parser.add_argument("--lambda-mult", type=float, default=0.5, help="MMR lambda (1=relevance, 0=diversity)")
    parser.add_argument("--category", help="filter: exact category")
    parser.add_argument("--priority", help="filter: exact priority (high/medium/low)")
    parser.add_argument("--author", help="filter: exact author")
    parser.add_argument("--status", help="filter: exact status (current/draft/deprecated)")
    parser.add_argument("--tags", nargs="*", help="filter: any-of tags")
    parser.add_argument("--date-from", help="filter: date >= value (ISO)")
    parser.add_argument("--date-to", help="filter: date <= value (ISO)")
    parser.add_argument("--min-views", type=int, help="filter: views >= value")
    parser.add_argument("--list-docs", action="store_true", help="list the built-in knowledge base")
    parser.add_argument("--index-stats", action="store_true", help="print index statistics")
    parser.add_argument("--json", action="store_true", help="machine-readable output")
    args = parser.parse_args(argv)

    if args.list_docs:
        _print_docs()
        return 0

    pipe = build_default_system()

    if args.index_stats:
        print(json.dumps(pipe.retriever.index.stats(), indent=2))
        return 0

    if not args.query:
        parser.error("--query is required (or use --list-docs / --index-stats)")

    filters: Dict[str, Any] = {}
    if args.category:
        filters["category"] = args.category
    if args.priority:
        filters["priority"] = args.priority
    if args.author:
        filters["author"] = args.author
    if args.status:
        filters["status"] = args.status
    if args.tags:
        filters["tags"] = args.tags
    date_spec: Dict[str, str] = {}
    if args.date_from:
        date_spec["$gte"] = args.date_from
    if args.date_to:
        date_spec["$lte"] = args.date_to
    if date_spec:
        filters["date"] = date_spec
    if args.min_views is not None:
        filters["views"] = {"$gte": args.min_views}

    ans = pipe.answer(
        args.query,
        k=args.k,
        filters=filters or None,
        ranker=args.ranker,
        lambda_mult=args.lambda_mult,
    )

    if args.json:
        print(
            json.dumps(
                {
                    "query": ans.query,
                    "filters": filters,
                    "ranker": args.ranker,
                    "results": [
                        {
                            "rank": r.rank,
                            "score": round(r.score, 4),
                            "doc_id": r.doc.doc_id,
                            "title": r.doc.title,
                            "snippet": r.doc.snippet(),
                            "metadata": r.doc.metadata,
                        }
                        for r in ans.results
                    ],
                    "summary": ans.summary,
                    "answer": ans.answer,
                    "confidence": round(ans.confidence, 4),
                    "groundedness": round(ans.groundedness, 4),
                    "elapsed_ms": round(ans.elapsed_ms, 2),
                },
                indent=2,
            )
        )
        return 0

    print(f"\nQuery: {ans.query}")
    print(f"Filters: {filters if filters else '(none)'} | Ranker: {args.ranker} | k={args.k}\n")
    _print_results(ans.results)
    print(f"\nAnswer:\n{ans.answer}")
    print(
        f"\nConfidence: {ans.confidence:.3f} | Groundedness: {ans.groundedness:.2f} "
        f"| Elapsed: {ans.elapsed_ms:.1f} ms"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""rag_system.py — Self-contained Retrieval-Augmented Generation (RAG) system.

Features
--------
* TF-IDF semantic index over a small knowledge base (pure Python stdlib:
  no external dependencies, no network calls).
* Rich metadata on every document (category, tags, priority, date, author,
  source, status, views, ...).
* Metadata filtering: exact match, membership, negation, existence, and
  ranges over dates and numbers.
* Relevance ranking: cosine similarity, plus Maximal Marginal Relevance (MMR)
  for diversity-aware reranking.
* Grounded answer generation with numbered citations, confidence and
  groundedness metrics.
* Python API + command-line interface.

Run the demo / tests:
    python test_rag.py

Run the CLI:
    python rag_system.py --query "rotate api keys" --category security --k 3
"""

