STOPWORDS = frozenset(
    """
    a about above after again against all am an and any are aren't as at be
    because been before being below between both but by can can't cannot could
    couldn't did didn't do does doesn't doing don't down during each few for
    from further had hadn't has hasn't have haven't having he he'd he'll he's
    her here here's hers herself him himself his how how's i i'd i'll i'm i've
    if in into is isn't it it's its itself let's me more most mustn't my myself
    no nor not of off on once only or other ought our ours ourselves out over
    own same shan't she she'd she'll she's should shouldn't so some such than
    that that's the their theirs them themselves then there there's these they
    they'd they'll they're they've this those through to too under until up
    very was wasn't we we'd we'll we're we've were weren't what what's when
    when's where where's which while who who's whom why why's with won't would
    wouldn't you you'd you'll you're you've your yours yourself yourselves use
    used using per via plus also etc
    """.split()
)


def stem(word: str) -> str:
    """Tiny suffix stripper — enough for a demo corpus (not full Porter)."""
    w = word
    if len(w) > 4 and w.endswith("ing"):
        w = w[:-3]
    elif len(w) > 4 and w.endswith("edly"):
        w = w[:-4]
    elif len(w) > 4 and w.endswith("ed"):
        w = w[:-2]
    elif len(w) > 4 and w.endswith("ies"):
        w = w[:-3] + "y"
    elif len(w) > 3 and w.endswith("es"):
        w = w[:-2]
    elif len(w) > 3 and w.endswith("s") and not w.endswith("ss"):
        w = w[:-1]
    elif len(w) > 4 and w.endswith("ly"):
        w = w[:-2]
    return w


def tokenize(text: str) -> List[str]:
    words = re.findall(r"[a-z0-9]+", text.lower())
    out: List[str] = []
    for w in words:
        if w in STOPWORDS or len(w) < 2:
            continue
        s = stem(w)
        if len(s) > 1:
            out.append(s)
    return out


# --------------------------------------------------------------------------- #
# Documents and metadata filtering
# --------------------------------------------------------------------------- #

@dataclass
class Document:
    doc_id: str
    title: str
    content: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    tokens: List[str] = field(default_factory=list, repr=False)

    def __post_init__(self) -> None:
        if not self.tokens:
            self.tokens = tokenize(f"{self.title}. {self.content}")

    def snippet(self, limit: int = 110) -> str:
        text = " ".join(self.content.split())
        return text if len(text) <= limit else text[: limit - 3] + "..."


_FILTER_OPS = {"$eq", "$ne", "$in", "$nin", "$gte", "$gt", "$lte", "$lt", "$exists"}


def _cmp(a: Any, b: Any) -> int:
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return (a > b) - (a < b)
    return (str(a) > str(b)) - (str(a) < str(b))


def _eq_any(doc_value: Any, expected: Any) -> bool:
    if isinstance(doc_value, list):
        return any(v == expected for v in doc_value)
    return doc_value == expected


def _ne_any(doc_value: Any, expected: Any) -> bool:
    if isinstance(doc_value, list):
        return all(v != expected for v in doc_value)
    return doc_value != expected


def _in_any(doc_value: Any, candidates: List[Any]) -> bool:
    if isinstance(doc_value, list):
        return any(v in candidates for v in doc_value)
    return doc_value in candidates


def _nin_any(doc_value: Any, candidates: List[Any]) -> bool:
    if isinstance(doc_value, list):
        return all(v not in candidates for v in doc_value)
    return doc_value not in candidates


def _apply_op(doc_value: Any, op: str, expected: Any) -> bool:
    if op == "$eq":
        return _eq_any(doc_value, expected)
    if op == "$ne":
        return _ne_any(doc_value, expected)
    if op == "$in":
        if not isinstance(expected, (list, tuple, set)):
            raise ValueError("$in expects a list of candidate values")
        return _in_any(doc_value, list(expected))
    if op == "$nin":
        if not isinstance(expected, (list, tuple, set)):
            raise ValueError("$nin expects a list of excluded values")
        return _nin_any(doc_value, list(expected))
    if op == "$exists":
        exists = doc_value is not None
        return exists if expected else not exists
    if doc_value is None:
        return False
    if op == "$gte":
        return any(_cmp(v, expected) >= 0 for v in (doc_value if isinstance(doc_value, list) else [doc_value]))
    if op == "$gt":
        return any(_cmp(v, expected) > 0 for v in (doc_value if isinstance(doc_value, list) else [doc_value]))
    if op == "$lte":
        return any(_cmp(v, expected) <= 0 for v in (doc_value if isinstance(doc_value, list) else [doc_value]))
    if op == "$lt":
        return any(_cmp(v, expected) < 0 for v in (doc_value if isinstance(doc_value, list) else [doc_value]))
    raise ValueError(f"unknown filter operator: {op}")


def matches_filters(doc: Document, filters: Optional[Dict[str, Any]]) -> bool:
    """Evaluate a metadata filter spec against a document.

    Supported specs:
        {"category": "security"}                  exact match (list-aware)
        {"tags": ["api", "auth"]}                 any-of membership
        {"category": {"$ne": "tutorial"}}         operators: $eq $ne $in $nin
                                                  $gte $gt $lte $lt $exists
        {"date": {"$gte": "2024-01-01", "$lte": "2024-12-31"}}   ranges
        {"views": {"$gte": 5000}}                 numeric ranges
    """
    if not filters:
        return True
    for key, spec in filters.items():
        value = doc.metadata.get(key)
        if isinstance(spec, dict):
            for op, expected in spec.items():
                if op not in _FILTER_OPS:
                    raise ValueError(f"unknown filter operator: {op}")
                if not _apply_op(value, op, expected):
                    return False
        elif isinstance(spec, list):
            if not _in_any(value, spec):
                return False
        else:
            if not _eq_any(value, spec):
                return False
    return True


# --------------------------------------------------------------------------- #
# TF-IDF semantic index
# --------------------------------------------------------------------------- #

class TFIDFIndex:
    """Sparse TF-IDF vector index with cosine similarity (pure stdlib)."""

    def __init__(self, documents: List[Document]):
        self.documents = list(documents)
        self.idf: Dict[str, float] = {}
        self._vectors: Dict[str, Dict[str, float]] = {}
        self._norms: Dict[str, float] = {}
        self._build()

    def _build(self) -> None:
        n = len(self.documents)
        df: Dict[str, int] = {}
        for doc in self.documents:
            for term in set(doc.tokens):
                df[term] = df.get(term, 0) + 1
        self.idf = {t: math.log((1 + n) / (1 + freq)) + 1.0 for t, freq in df.items()}
        for doc in self.documents:
            tf = Counter(doc.tokens)
            vec = {t: (1.0 + math.log(c)) * self.idf.get(t, 0.0) for t, c in tf.items()}
            norm = math.sqrt(sum(w * w for w in vec.values())) or 1.0
            self._vectors[doc.doc_id] = vec
            self._norms[doc.doc_id] = norm

    def query_vector(self, query: str) -> Tuple[Dict[str, float], float]:
        tf = Counter(tokenize(query))
        vec = {t: (1.0 + math.log(c)) * self.idf.get(t, 0.0) for t, c in tf.items()}
        norm = math.sqrt(sum(w * w for w in vec.values())) or 1.0
        return vec, norm

    def cosine(self, qvec: Dict[str, float], qnorm: float, doc_id: str) -> float:
        dvec = self._vectors[doc_id]
        small, big = (qvec, dvec) if len(qvec) <= len(dvec) else (dvec, qvec)
        dot = sum(w * big.get(t, 0.0) for t, w in small.items())
        return dot / (qnorm * self._norms[doc_id])

    def doc_cosine(self, id_a: str, id_b: str) -> float:
        va, vb = self._vectors[id_a], self._vectors[id_b]
        small, big = (va, vb) if len(va) <= len(vb) else (vb, va)
        dot = sum(w * big.get(t, 0.0) for t, w in small.items())
        return dot / (self._norms[id_a] * self._norms[id_b])

    def stats(self) -> Dict[str, Any]:
        n = len(self.documents) or 1
        return {
            "documents": len(self.documents),
            "vocabulary": len(self.idf),
            "avg_tokens": round(sum(len(d.tokens) for d in self.documents) / n, 1),
        }


# --------------------------------------------------------------------------- #
# Retrieval: metadata filtering + relevance ranking (cosine / MMR)
# --------------------------------------------------------------------------- #

@dataclass
class RetrievedDoc:
    doc: Document
    score: float
    rank: int = 0


class Retriever:
    def __init__(self, documents: List[Document], index: Optional[TFIDFIndex] = None):
        self.documents = {d.doc_id: d for d in documents}
        self.index = index or TFIDFIndex(documents)

    def filtered_ids(self, filters: Optional[Dict[str, Any]]) -> List[str]:
        return [d.doc_id for d in self.index.documents if matches_filters(d, filters)]

    def search(
        self,
        query: str,
        k: int = 5,
        filters: Optional[Dict[str, Any]] = None,
        ranker: str = "cosine",
        lambda_mult: float = 0.5,
        fetch_k: Optional[int] = None,
    ) -> List[RetrievedDoc]:
        """Rank documents by relevance to `query`, restricted by `filters`.

        ranker="cosine": plain relevance ranking.
        ranker="mmr":    Maximal Marginal Relevance — lambda_mult * relevance
                         - (1 - lambda_mult) * redundancy with already-picked
                         results (lambda 1.0 = pure relevance, 0.0 = pure
                         diversity).
        """
        qvec, qnorm = self.index.query_vector(query)
        ids = self.filtered_ids(filters)
        if not ids:
            return []
        scored = sorted(
            ((did, self.index.cosine(qvec, qnorm, did)) for did in ids),
            key=lambda x: x[1],
            reverse=True,
        )
        if ranker == "mmr":
            fetch_k = fetch_k or max(k * 3, 10)
            selected = self._mmr_select(qvec, qnorm, [d for d, _ in scored[:fetch_k]], k, lambda_mult)
            results = [
                RetrievedDoc(self.documents[did], self.index.cosine(qvec, qnorm, did))
                for did in selected
            ]
        elif ranker == "cosine":
            results = [RetrievedDoc(self.documents[did], s) for did, s in scored[:k]]
        else:
            raise ValueError(f"unknown ranker: {ranker}")
        for rank, r in enumerate(results, start=1):
            r.rank = rank
        return results

    def _mmr_select(
        self,
        qvec: Dict[str, float],
        qnorm: float,
        candidate_ids: List[str],
        k: int,
        lambda_mult: float,
    ) -> List[str]:
        remaining = list(candidate_ids)
        selected: List[str] = []
        while len(selected) < k and remaining:
            best_id, best_val = None, -1e18
            for cid in remaining:
                rel = self.index.cosine(qvec, qnorm, cid)
                max_sim = (
                    max(self.index.doc_cosine(cid, s) for s in selected) if selected else 0.0
                )
                val = lambda_mult * rel - (1.0 - lambda_mult) * max_sim
                if val > best_val:
                    best_val, best_id = val, cid
            selected.append(best_id)
            remaining.remove(best_id)
        return selected


# --------------------------------------------------------------------------- #
# Grounded answer generation with citations
# --------------------------------------------------------------------------- #

@dataclass
class RAGAnswer:
    query: str
    answer: str
    summary: str
    confidence: float
    groundedness: float
    citations: List[Dict[str, Any]]
    results: List[RetrievedDoc]
    elapsed_ms: float


class GroundedAnswerGenerator:
    """Builds a grounded answer: every sentence is drawn verbatim from a
    retrieved source and annotated with a numbered citation."""

    def __init__(self, max_sources: int = 4):
        self.max_sources = max_sources

    def _best_sentence(self, doc: Document, qterms: set) -> str:
        sentences = [s for s in re.split(r"(?<=[.!?])\s+", doc.content.strip()) if s]
        if not sentences:
            return doc.content.strip()
        best, best_score = sentences[0], -1.0
        for idx, s in enumerate(sentences):
            overlap = len(set(tokenize(s)) & qterms)
            score = overlap + (0.1 if idx == 0 else 0.0)
            if score > best_score:
                best, best_score = s, score
        return best

    def generate(self, query: str, results: List[RetrievedDoc]) -> Dict[str, Any]:
        qterms = set(tokenize(query))
        citations: List[Dict[str, Any]] = []
        evidence: List[Dict[str, Any]] = []
        for i, r in enumerate(results[: self.max_sources], start=1):
            sentence = self._best_sentence(r.doc, qterms)
            meta = r.doc.metadata
            citations.append(
                {
                    "index": i,
                    "doc_id": r.doc.doc_id,
                    "title": r.doc.title,
                    "source": meta.get("source", "unknown"),
                    "score": round(r.score, 4),
                }
            )
            evidence.append(
                {
                    "sentence": sentence,
                    "doc_id": r.doc.doc_id,
                    "title": r.doc.title,
                    "source": meta.get("source", "unknown"),
                    "score": round(r.score, 4),
                }
            )
        if not evidence:
            answer = "No relevant documents were found for this query."
            return {
                "answer": answer,
                "summary": answer,
                "confidence": 0.0,
                "groundedness": 1.0,
                "citations": citations,
            }
        top = evidence[0]
        summary = f"According to '{top['title']}' ({top['source']}), {top['sentence'].rstrip('.')}."
        lines = [
            f"[{c['index']}] {e['sentence']} — from '{e['title']}' ({e['source']})"
            for e, c in zip(evidence, citations)
        ]
        answer = "I found the following grounded evidence in the knowledge base:\n\n" + "\n".join(lines)
        confidence = sum(e["score"] for e in evidence) / len(evidence)
        src_text = " ".join(r.doc.content for r in results)
        verbatim = sum(1 for e in evidence if e["sentence"].strip() in src_text)
        groundedness = verbatim / len(evidence)
        return {
            "answer": answer,
            "summary": summary,
            "confidence": confidence,
            "groundedness": groundedness,
            "citations": citations,
        }


class RAGPipeline:
    """End-to-end RAG: retrieve (filter + rank) -> generate grounded answer."""

    def __init__(
        self,
        documents: Optional[List[Document]] = None,
        retriever: Optional[Retriever] = None,
        generator: Optional[GroundedAnswerGenerator] = None,
    ):
        if retriever is None:
            if not documents:
                raise ValueError("provide documents or a retriever")
            retriever = Retriever(documents)
        self.retriever = retriever
        self.generator = generator or GroundedAnswerGenerator()

    def answer(
        self,
        query: str,
        k: int = 4,
        filters: Optional[Dict[str, Any]] = None,
        ranker: str = "cosine",
        lambda_mult: float = 0.5,
        fetch_k: Optional[int] = None,
    ) -> RAGAnswer:
        t0 = time.perf_counter()
        results = self.retriever.search(
            query, k=k, filters=filters, ranker=ranker,
            lambda_mult=lambda_mult, fetch_k=fetch_k,
        )
        gen = self.generator.generate(query, results)
        elapsed_ms = (time.perf_counter() - t0) * 1000.0
        return RAGAnswer(
            query=query,
            answer=gen["answer"],
            summary=gen["summary"],
            confidence=gen["confidence"],
            groundedness=gen["groundedness"],
            citations=gen["citations"],
            results=results,
            elapsed_ms=elapsed_ms,
        )


